results={}
for i in reservation['ids']:
 k=str(i);v=raw[k];r=v['record'];status,read,gap=notes[i];a=r['source_url'].split('/')[-1]
 prov={x:y for x,y in v.items() if x!='record'};prov['statement_sha256_utf8']=h(r['statement'].encode());prov['raw_file']='raw/'+k+'.jsonl'
 assert h((p/prov['raw_file']).read_bytes())==prov['raw_sha256']
 results[k]={'mathdb_id':i,'title':r['title'],'literal_statement':r['statement'],'full_parsed_record':r,'literal_provenance':prov,'disposition':status,'primary_locations_read':read,'review_depth':{'literal_record':'Full exact parsed record and statement read; raw newline preserved','versions_fetched':versions[a],'version_reading':'Selected target passages compared; numbering changes manually investigated. Not a full audit of every version proof, definition or cited dependency. focused-version-passages.txt has retained no-match diagnostics.','journal_corrections_citing':'Only expressly named proof passages read. Complete latest journal, correction, withdrawal and citing-body audit NOT completed. No novelty clearance.','figures':'No visual figure audit; textual printed recipes read where specified. No claim of all printed objects reviewed.'},'source_receipts':['sources/abs-receipts.json','sources/pdf-receipts.json','sources/extra-receipts.json'],'ordinary_attempts':'ORDINARY-ATTEMPTS.md','precise_gap_or_exclusion':gap,'historical_screen':'history-matches.txt: exact IDs, titles and source identifiers searched across project Markdown and results/review JSON. Related r274 cutset and r266 index/bias notes read; not all historical proof bodies. Substring false positives retained, not treated as discoveries.','current_registry':'REGISTRY-LIMITS.md; current retrieval denied, cached catalogue is routing only','source_qualified':False,'prior_art_cleared':False,'pi_assignment_recommended':False,'lean_endpoint':None,'independent_review':None,'accepted':False,'credit':0}
assert len(results)==20 and set(results)==set(map(str,reservation['ids']))
(p/'results.json').write_text(json.dumps(results,indent=2,ensure_ascii=False)+'\n')
(p/'reservation-checks.json').write_text(json.dumps({'expected_sha256':expected,'before_sha256':expected,'after_sha256':h((p/'reservation.json').read_bytes()),'before_observed':'First administrative tool read printed actual SHA before any research write','after_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'exact_20_keys':True,'reservation_unchanged':True,'reselection_or_reserve_execution':False},indent=2)+'\n')
